compile.workshop:
variables {
    global:
        0: value
}

rule ("[Child] included rule") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(value, 2);
    }
}

rule ("main-file entry") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(value, 1);
    }
}

